16	// prepareReportScenario 构建含结束时记录与退回/补充历史的交接场景：
17	// a 已结束（I001、I002 结束时未关闭，I003 结束前已关闭），h 为 a→b 的交接；
18	// I002 被退回一轮后由交班人补充并重新提交（恢复待处理），I001 已确认接收，
19	// 整份交接仍未完成。
20	func prepareReportScenario(t *testing.T, f *fixture) (Shift, Shift, []Item, Handover) {
21		t.Helper()
22		a, b, items := prepareHandover(t, f)
23		h, err := f.svc.CreateHandover(a.ID, b.ID)
