197			t.Fatalf("前置：接班班次应看到交接 %s，got %+v", h.ID, rb.Incoming)
198		}
199		ie := findEntryOf(t, rb.Incoming[0], idA)
200		origIncomingProcessedAt := *ie.ProcessedAt
201		ie.Status = EntryReturned
202		ie.Operator = "篡改人"
203		*ie.ProcessedAt = forge
204		gotIn := rb.Results[idA][0].Entry
205		if gotIn.Status != EntryConfirmed || gotIn.Operator != "李四" ||
206			gotIn.ProcessedAt == nil || !gotIn.ProcessedAt.Equal(origIncomingProcessedAt) {
207			t.Fatalf("改动接班清单不应连带改掉逐项结果：%+v", gotIn)
208		}
209		rb.Results[idB][0].Entry.Rounds[0].Reason = "篡改原因"
210		ib := findEntryOf(t, rb.Incoming[0], idB)
211		if ib.Rounds[0].Reason != "需要补充细节" {
212			t.Fatalf("改动逐项结果不应连带改掉接班清单：%+v", ib.Rounds[0])
