216	// TestEarlierReportSurvivesLaterProcessing：保留报告后，接班人通过已有功能正常
217	// 接收事项、修改并关闭它，系统的新查询反映这些成功操作，但先前报告仍保留
218	// 查询时的事项归属、负责人、关闭情况与交接进度；退回与补充历史、处理时间与
219	// 交接完成时间各属各自报告取得时的事实，旧报告不混入后来新增的经过。
220	func TestEarlierReportSurvivesLaterProcessing(t *testing.T) {
221		f := newFixture(t)
222		a, b, items := prepareHandover(t, f)
223		h, err := f.svc.CreateHandover(a.ID, b.ID)
224		if err != nil {
