313	// TestEmptyAndLegacyReportsAlsoIndependent：没有事项或关联交接的班次、空清单
314	// 结束的班次与缺少结束时记录的旧数据班次都能正常取得报告，同样遵守独立性
315	// 约定；空清单与缺少历史记录保持区别，旧数据的当前值不能宣称为结束时事实。
316	func TestEmptyAndLegacyReportsAlsoIndependent(t *testing.T) {
