327			t.Fatalf("空班次报告应为空清单：%+v", rep)
328		}
329		// 向报告中塞入假事项、假结果、假交接并改班次摘要，不影响再次查询。
330		rep.Items = append(rep.Items, Item{ID: "I999", Content: "篡改事项"})
331		rep.Results["I999"] = []EntryView{{HandoverID: "H999"}}
332		rep.Outgoing = &Handover{ID: "H999"}
333		rep.Shift.Owner = "篡改负责人"
334		again, err := f.svc.ShiftReport(e.ID)
335		if err != nil {
336			t.Fatalf("report again: %v", err)
337		}
338		if len(again.Items) != 0 || again.Outgoing != nil || len(again.Incoming) != 0 ||
339			len(again.Results) != 0 || again.Shift.Owner != "孙八" {
340			t.Fatalf("改动空班次的报告不应影响再次查询：%+v", again)
341		}
342	
343		// 空清单结束：留下空的结束时记录，与缺少历史记录相区别。
344		if _, err := f.svc.CloseShift(e.ID); err != nil {
345			t.Fatalf("close: %v", err)
346		}
347		closed, err := f.svc.ShiftReport(e.ID)
348		if err != nil {
349			t.Fatalf("report closed: %v", err)
350		}
351		if !closed.ItemsAtClose || closed.HistoryIncomplete || len(closed.CloseItems) != 0 {
352			t.Fatalf("空清单结束应留下空的结束时记录，且不是历史不完整：%+v", closed)
353		}
354		closed.CloseItems = append(closed.CloseItems, CloseItemSnapshot{ItemID: "I999", Content: "篡改事项"})
355		closed.Shift.CloseRecord.Items = append(closed.Shift.CloseRecord.Items, CloseItemSnapshot{ItemID: "I999"})
356		closedAgain, err := f.svc.ShiftReport(e.ID)
357		if err != nil {
358			t.Fatalf("report closed again: %v", err)
359		}
360		if !closedAgain.ItemsAtClose || closedAgain.HistoryIncomplete || len(closedAgain.CloseItems) != 0 {
361			t.Fatalf("改动报告不应影响空清单结束时记录：%+v", closedAgain)
362		}
363	
364		// 旧数据：已结束但缺少结束时记录的班次。
365		dir := t.TempDir()
366		path := filepath.Join(dir, "data.json")
367		closedAt := tsDay(2, 16, 0)
368		createdAt := tsDay(2, 8, 0)
369		data := Data{
370			ShiftSeq: 1,
371			ItemSeq:  1,
372			Shifts: []Shift{
373				{ID: "S001", Position: "调度", Owner: "张三", Start: tsDay(2, 8, 0), End: tsDay(2, 16, 0),
374					CreatedAt: createdAt, Closed: true, ClosedAt: &closedAt},
375			},
376			Items: []Item{{
377				ID: "I001", OriginShiftID: "S001", ShiftIDs: []string{"S001"}, CurrentShiftID: "S001",
378				Content: "旧内容", Severity: SeverityNormal, FollowOwner: "王五", CreatedAt: createdAt,
379			}},
380		}
381		raw, err := json.Marshal(data)
382		if err != nil {
383			t.Fatalf("marshal: %v", err)
384		}
385		if err := os.WriteFile(path, raw, 0o644); err != nil {
386			t.Fatalf("write: %v", err)
387		}
388		store, err := Open(path)
389		if err != nil {
390			t.Fatalf("open: %v", err)
391		}
392		svc := NewService(store)
393	
394		legacy, err := svc.ShiftReport("S001")
395		if err != nil {
396			t.Fatalf("legacy report: %v", err)
397		}
398		if !legacy.HistoryIncomplete || legacy.ItemsAtClose || len(legacy.CloseItems) != 0 {
399			t.Fatalf("旧数据应明确历史记录不完整，当前值不能宣称为结束时事实：%+v", legacy)
400		}
401		if len(legacy.Items) != 1 || legacy.Items[0].Content != "旧内容" {
402			t.Fatalf("旧数据应展示当前事项信息：%+v", legacy.Items)
403		}
404		// 改动旧数据报告中的当前事项（内容、关闭信息、流经班次），再次查询仍得
405		// 原来的当前信息，且仍标明历史不完整、不变成结束时事实。
406		legacy.Items[0].Content = "篡改旧内容"
407		legacy.Items[0].Closed = true
408		legacy.Items[0].ClosedAt = &forge
409		legacy.Items[0].CloseOperator = "篡改人"
410		legacy.Items[0].ShiftIDs = append(legacy.Items[0].ShiftIDs, "S999")
411		legacyAgain, err := svc.ShiftReport("S001")
412		if err != nil {
413			t.Fatalf("legacy report again: %v", err)
414		}
415		if !legacyAgain.HistoryIncomplete || legacyAgain.ItemsAtClose || len(legacyAgain.CloseItems) != 0 {
416			t.Fatalf("改动报告不得把当前值变成结束时事实：%+v", legacyAgain)
417		}
418		if len(legacyAgain.Items) != 1 || legacyAgain.Items[0].Content != "旧内容" ||
419			legacyAgain.Items[0].Closed || len(legacyAgain.Items[0].ShiftIDs) != 1 {
420			t.Fatalf("改动旧数据报告不应影响再次查询的当前信息：%+v", legacyAgain.Items)
421		}
422	}
